// ─── File: PersuasionDemo.java ───
// Single runnable file with multiple top-level, package-private classes.

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Handler;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class PersuasionDemo {

    private static final Logger log = Logger.getLogger(PersuasionDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger rootLogger = Logger.getLogger("");
        for (Handler handler : rootLogger.getHandlers()) {
            rootLogger.removeHandler(handler);
        }
        ConsoleHandler consoleHandler = new ConsoleHandler();
        consoleHandler.setFormatter(new BankLogFormatter());
        consoleHandler.setLevel(Level.ALL);
        rootLogger.addHandler(consoleHandler);
        rootLogger.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info(() -> "Proof-of-concept: batch vs one-at-a-time settlement at " + BANK_NAME);

        List<Transfer> transfers = new ArrayList<>();
        transfers.add(new Transfer("TXF-1", "SAV2001", "CUR3001", new BigDecimal("50000")));
        transfers.add(new Transfer("TXF-2", "CUR3001", "SAV2001", new BigDecimal("-10"))); // invalid
        transfers.add(new Transfer("TXF-3", "SAV2001", "CUR3001", new BigDecimal("25000")));
        transfers.add(new Transfer("TXF-4", "CUR3001", "SAV2001", new BigDecimal("0")));    // invalid

        OneAtATimeProcessor oneAtATime = new OneAtATimeProcessor();
        BatchProcessor batch = new BatchProcessor();

        log.info("OLD approach (one at a time, stops at first error):");
        oneAtATime.process(transfers);

        log.info("NEW approach (batch, validates all, reports every failure at once):");
        batch.process(transfers);
    }
}

// ─── Would be in model/Transfer.java in a real project ───
class Transfer {
    private final String id;
    private final String from;
    private final String to;
    private final BigDecimal amount;

    Transfer(String id, String from, String to, BigDecimal amount) {
        this.id = id;
        this.from = from;
        this.to = to;
        this.amount = amount;
    }

    String getId() { return id; }
    String getFrom() { return from; }
    String getTo() { return to; }
    BigDecimal getAmount() { return amount; }
    boolean isValid() { return amount.compareTo(BigDecimal.ZERO) > 0; }
}

// ─── Would be in processor/OneAtATimeProcessor.java in a real project ───
// The old approach: process each transfer, and the first bad one halts the run.
class OneAtATimeProcessor {
    private static final Logger log = Logger.getLogger(OneAtATimeProcessor.class.getName());

    void process(List<Transfer> transfers) {
        int done = 0;
        for (Transfer t : transfers) {
            if (!t.isValid()) {
                log.severe(() -> "HALTED at " + t.getId() + " (invalid amount " + t.getAmount()
                        + "). Remaining transfers not attempted.");
                log.warning(() -> "Processed " + done + " of " + transfers.size()
                        + " before stopping.");
                return;
            }
            done++;
            log.info(() -> "Settled " + t.getId());
        }
    }
}

// ─── Would be in processor/BatchProcessor.java in a real project ───
// The new approach: validate everything first, settle valid ones, report all failures.
class BatchProcessor {
    private static final Logger log = Logger.getLogger(BatchProcessor.class.getName());

    void process(List<Transfer> transfers) {
        List<String> failures = new ArrayList<>();
        for (Transfer t : transfers) {
            if (!t.isValid()) {
                failures.add(t.getId() + " (amount " + t.getAmount() + ")");
            }
        }
        int settled = 0;
        for (Transfer t : transfers) {
            if (t.isValid()) {
                settled++;
                log.info(() -> "Settled " + t.getId());
            }
        }
        final int settledCount = settled;
        log.info(() -> "Batch settled " + settledCount + " of " + transfers.size() + " transfers.");
        if (!failures.isEmpty()) {
            log.warning(() -> "All failures surfaced at once: " + failures);
        }
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
                record.getMillis(),
                record.getLevel().getName(),
                record.getSourceClassName() != null
                        ? record.getSourceClassName().substring(
                                record.getSourceClassName().lastIndexOf('.') + 1)
                        : "Unknown",
                record.getMessage());
    }
}
